// S09-T01: with three keyboards bound to different layers, a note from one
// device only triggers layers whose source is that device or "All keyboards".
func TestPerDeviceRoutingIsolatesKeyboards(t *testing.T) {
	f := &FakeEngine{}
	c := NewController(f, nil)
	c.SetScene(Scene{
		Name:       "t",
		MasterGain: 0.6,
		Layers: []Layer{
			{Channel: 0, Enabled: true, Volume: 100, Pan: 64, Source: "Device A", KeyLow: 0, KeyHigh: 127},
			{Channel: 1, Enabled: true, Volume: 100, Pan: 64, Source: "Device B", KeyLow: 0, KeyHigh: 127},
			{Channel: 2, Enabled: true, Volume: 100, Pan: 64, Source: SourceAny, KeyLow: 0, KeyHigh: 127},
		},
	})
	f.Reset()

	// A note from Device B (via the normalized MIDI event path).
	c.handleMIDI(midiio.Event{Device: "Device B", Type: midiio.NoteOn, Key: 64, Velocity: 100})

	on := f.CallsOf("NoteOn")
	assert.ElementsMatch(t, []string{
		"NoteOn ch=1 key=64 vel=100", // Device B layer
		"NoteOn ch=2 key=64 vel=100", // All-keyboards layer
	}, on, "Device A layer (ch0) must NOT sound for a Device B note")
}

package midimap

import (
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// S10-T02: every bundled preset is well-formed — it maps the GM volume/pan CCs
// and every CC number is in the valid 0..127 range.
func TestPresetsAreWellFormed(t *testing.T) {
	for _, name := range Names() {
		m := Get(name)
		require.Equal(t, name, m.Name, "Get(%q) returned wrong map", name)

		// Volume and pan are present and on the GM standards.
		volCC := findCC(m, Volume)
		panCC := findCC(m, Pan)
		require.NotEqual(t, -1, volCC, "%s: missing Volume mapping", name)
		require.NotEqual(t, -1, panCC, "%s: missing Pan mapping", name)
		assert.Equal(t, 7, volCC, "%s: volume should be CC7", name)
		assert.Equal(t, 10, panCC, "%s: pan should be CC10", name)

		for cc, action := range m.CC {
			assert.GreaterOrEqual(t, cc, 0, "%s: CC %d out of range", name, cc)
			assert.LessOrEqual(t, cc, 127, "%s: CC %d out of range", name, cc)
			assert.NotEqual(t, None, action, "%s: CC %d maps to None", name, cc)
		}
	}
}

func TestUnknownPresetFallsBackToGeneric(t *testing.T) {
	assert.Equal(t, "Generic GM", Get("nope").Name)
}

func findCC(m Map, a Action) int {
	for cc, act := range m.CC {
		if act == a {
			return cc
		}
	}
	return -1
}

package mp3

import (
